// The Cap'n Proto bindings are checked in under src/generated/, so building
// this crate never needs the `capnp` compiler. Regenerate with
// `tools/regenerate-capnp.sh crates/runtime/runtime-fs`, then update the fingerprints
// below from the schema and generated bytes in their declared order. A schema
// edited without regenerating, or bindings edited by hand, fail here.

const EXPECTED_SCHEMA_FNV1A: u64 = 0x4a89_e3c4_8adc_7490;
const EXPECTED_BINDINGS_FNV1A: u64 = 0x7306_173d_b0e3_8e15;
const SCHEMAS: [&str; 2] = ["schema/fs.capnp", "schema/blobs.capnp"];
const GENERATED: [&str; 2] = ["src/generated/fs_capnp.rs", "src/generated/blobs_capnp.rs"];

fn fingerprint(paths: &[&str]) -> std::io::Result<u64> {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for path in paths {
        println!("cargo:rerun-if-changed={path}");
        for byte in std::fs::read(path)? {
            hash = (hash ^ u64::from(byte)).wrapping_mul(0x100_0000_01b3);
        }
    }
    Ok(hash)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stale = if fingerprint(&SCHEMAS)? != EXPECTED_SCHEMA_FNV1A {
        "the Cap'n Proto schema changed without regenerating its bindings"
    } else if fingerprint(&GENERATED)? != EXPECTED_BINDINGS_FNV1A {
        "the checked-in Cap'n Proto bindings were edited by hand"
    } else {
        return Ok(());
    };
    Err(std::io::Error::new(
        std::io::ErrorKind::InvalidData,
        format!("{stale}; run `tools/regenerate-capnp.sh crates/runtime/runtime-fs` and update the build.rs fingerprints"),
    )
    .into())
}
